?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Editar Livro</title><?php include 'includes_painel/head.php'; ?><?php include '_form_style.php'; ?></head><body><?php include 'includes_painel/header.php'; ?><div class="crud"><div class="card"><h1>Editar Livro</h1><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><div class="grid"><div class="campo"><label>Título</label><input name="titulo" required value="<?=h($row['titulo'])?>"></div><div class="campo"><label>ISBN</label><input name="isbn" value="<?=h($row['isbn']??'')?>"></div><div class="campo"><label>Autor</label><input name="autor" value="<?=h($row['autor']??'')?>"></div><div class="campo"><label>Categoria</label><input name="categoria" value="<?=h($row['categoria']??'')?>"></div><div class="campo"><label>Ano de publicação</label><input type="number" name="ano_publicacao" value="<?=h($row['ano_publicacao']??'')?>"></div><div class="campo"><label>Status</label><select name="status"><?php foreach(['Disponível','Em Revisão','Arquivado'] as $op):?><option <?=($row['status']??'')===$op?'selected':''?>><?=h($op)?></option><?php endforeach;?></select></div></div><div class="acoes"><button class="btn salvar">Salvar alterações</button><a class="btn voltar" href="lista_livros.php">Cancelar</a></div></form></div></div></body></html>
